use crate::account::Kind;
use crate::money::{money, Money};

/// Convert the number a statement PRINTS into the signed convention.
///
/// A debt statement prints what you owe as a positive number, because from the institution's side it
/// is an asset. Net worth needs the other side of that. A card in credit (you overpaid) prints a
/// negative and comes back positive, which is also right — negation is the whole rule and it holds
/// in both directions rather than being a special case for the common one.
pub fn from_statement_balance(kind: Kind, printed: Money) -> Money {
    if kind.is_debt() {
        money(-printed.minor, printed.currency)
    } else {
        printed
    }
}
